# Pseudocode for cost guardrail

def check_budget(current_usage, daily_budget):
    if current_usage >= 0.95 * daily_budget:
        return "reject"
    elif current_usage >= 0.8 * daily_budget:
        return "throttle"
    else:
        return "allow"

# Example usage
current_usage = 850000
daily_budget = 1000000
action = check_budget(current_usage, daily_budget)
print(f"Action: {action}")
